// 1. Khởi tạo mảng 12 tháng
const months = Array.from({ length: 12 }, (_, i) => {
  const m = (i + 1).toString().padStart(2, '0');
  return `2024-${m}`;
});

const monthlyStats = {};
months.forEach(m => {
  monthlyStats[m] = { netRevenue: 0, cogs: 0, grossProfit: 0 };
});

// 2. Xử lý & gom nhóm dữ liệu theo tháng
data.forEach(r => {
  if (r['Order_Status'] === 'Cancelled') return;

  const rawDate = r['Order_Date'] ? String(r['Order_Date']).trim() : '';
  const monthKey = rawDate.substring(0, 7);

  if (monthlyStats[monthKey]) {
    const qty = Number(r['Order_Quantity']) || 0;
    const price = Number(r['Unit_Price']) || 0;
    const cost = Number(r['Unit_Cost']) || 0;
    const discountRate = Number(r['Discount_Rate']) || 0;

    let netRev = Number(r['Net_Revenue']);
    if (isNaN(netRev) || netRev === 0) {
      const gross = qty * price;
      netRev = gross - (gross * discountRate);
    }

    const cogs = qty * cost;
    const profit = netRev - cogs;

    monthlyStats[monthKey].netRevenue += netRev;
    monthlyStats[monthKey].cogs += cogs;
    monthlyStats[monthKey].grossProfit += profit;
  }
});

const netRevData = months.map(m => Math.round((monthlyStats[m].netRevenue / 1e9) * 100) / 100);
const cogsData = months.map(m => Math.round((monthlyStats[m].cogs / 1e9) * 100) / 100);
const marginData = months.map(m => {
  const rev = monthlyStats[m].netRevenue;
  const profit = monthlyStats[m].grossProfit;
  return rev > 0 ? Math.round((profit / rev) * 1000) / 10 : 0;
});

// 3. Cấu hình Option ECharts - Theme Sáng
return {
  backgroundColor: '#ffffff',
  title: {
    text: 'Xu Hướng Doanh Thu, Giá Vốn & Biên Lợi Nhuận Gộp Năm 2024',
    subtext: 'Đơn vị: Tỷ VNĐ (Doanh thu & Chi phí) | % (Tỷ suất lợi nhuận)',
    left: 'center',
    top: 16,
    textStyle: { color: '#0f172a', fontSize: 16, fontWeight: 700 },
    subtextStyle: { color: '#64748b', fontSize: 12 }
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross',
      crossStyle: { color: '#94a3b8' }
    },
    backgroundColor: '#ffffff',
    borderColor: '#e2e8f0',
    borderWidth: 1,
    padding: [12, 16],
    extraCssText: 'box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); border-radius: 8px;',
    textStyle: { color: '#1e293b' },
    formatter: function(params) {
      const month = params[0].name;
      let res = `<div style="font-weight:700;color:#0f172a;margin-bottom:8px;font-size:13px;">Tháng: ${month}</div>`;
      params.forEach(p => {
        const val = p.seriesType === 'line' ? `${p.value}%` : `${p.value} tỷ VNĐ`;
        res += `<div style="display:flex;justify-content:space-between;align-items:center;gap:20px;margin:4px 0;font-size:12px;">
                  <span style="color:#475569;">${p.marker} ${p.seriesName}:</span>
                  <span style="font-weight:700;color:#0f172a;">${val}</span>
                </div>`;
      });
      return res;
    }
  },
  legend: {
    data: ['Doanh Thu Thuần', 'Giá Vốn (COGS)', 'Biên Lợi Nhuận Gộp'],
    top: 58,
    textStyle: { color: '#475569', fontSize: 12 }
  },
  grid: {
    left: '4%',
    right: '5%',
    bottom: '8%',
    top: '20%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: months.map(m => `T${parseInt(m.split('-')[1])}`),
    axisLine: { lineStyle: { color: '#cbd5e1' } },
    axisTick: { alignWithLabel: true },
    axisLabel: { color: '#64748b', fontWeight: 500 }
  },
  yAxis: [
    {
      type: 'value',
      name: 'Tỷ VNĐ',
      nameTextStyle: { color: '#64748b', align: 'right' },
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { color: '#64748b' },
      splitLine: { lineStyle: { color: '#f1f5f9', type: 'dashed' } }
    },
    {
      type: 'value',
      name: '% Margin',
      nameTextStyle: { color: '#64748b', align: 'left' },
      min: 0,
      max: 40,
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { color: '#64748b', formatter: '{value}%' },
      splitLine: { show: false }
    }
  ],
  series: [
    {
      name: 'Doanh Thu Thuần',
      type: 'bar',
      data: netRevData,
      barMaxWidth: 22,
      itemStyle: {
        borderRadius: [4, 4, 0, 0],
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
          { offset: 0, color: '#2563eb' },
          { offset: 1, color: '#60a5fa' }
        ])
      }
    },
    {
      name: 'Giá Vốn (COGS)',
      type: 'bar',
      data: cogsData,
      barMaxWidth: 22,
      itemStyle: {
        borderRadius: [4, 4, 0, 0],
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
          { offset: 0, color: '#94a3b8' },
          { offset: 1, color: '#cbd5e1' }
        ])
      }
    },
    {
      name: 'Biên Lợi Nhuận Gộp',
      type: 'line',
      yAxisIndex: 1,
      data: marginData,
      smooth: true,
      symbol: 'circle',
      symbolSize: 8,
      itemStyle: {
        color: '#f59e0b',
        borderWidth: 2,
        borderColor: '#ffffff'
      },
      lineStyle: { width: 3, color: '#f59e0b' }
    }
  ]
};

// 1. Gom nhóm doanh thu và lợi nhuận gộp theo từng ngành hàng
const categoryMap = {};

data.forEach(r => {
  if (r['Order_Status'] === 'Cancelled') return;

  const cat = r['Category'] ? String(r['Category']).trim() : 'Khác';
  if (!categoryMap[cat]) {
    categoryMap[cat] = { netRevenue: 0, grossProfit: 0, orderCount: 0 };
  }

  const qty = Number(r['Order_Quantity']) || 0;
  const price = Number(r['Unit_Price']) || 0;
  const cost = Number(r['Unit_Cost']) || 0;
  const discountRate = Number(r['Discount_Rate']) || 0;

  let netRev = Number(r['Net_Revenue']);
  if (isNaN(netRev) || netRev === 0) {
    const gross = qty * price;
    netRev = gross - (gross * discountRate);
  }

  const cogs = qty * cost;
  const profit = netRev - cogs;

  categoryMap[cat].netRevenue += netRev;
  categoryMap[cat].grossProfit += profit;
  categoryMap[cat].orderCount += 1;
});

// Chuyển đổi dữ liệu và tính tổng doanh thu
let totalNetRev = 0;
const donutData = Object.keys(categoryMap)
  .map(cat => {
    const rev = categoryMap[cat].netRevenue;
    const profit = categoryMap[cat].grossProfit;
    const margin = rev > 0 ? (profit / rev) * 100 : 0;
    const revBillion = Math.round((rev / 1e9) * 100) / 100;
    const profitBillion = Math.round((profit / 1e9) * 100) / 100;
    totalNetRev += revBillion;

    return {
      name: cat,
      value: revBillion,
      profitBillion: profitBillion,
      marginPercent: Math.round(margin * 10) / 10,
      orders: categoryMap[cat].orderCount
    };
  })
  .sort((a, b) => b.value - a.value);

totalNetRev = Math.round(totalNetRev * 100) / 100;

// 2. Cấu hình Option ECharts Donut Chart (Theme Sáng)
return {
  backgroundColor: '#ffffff',
  title: [
    {
      text: 'Cơ Cấu Doanh Thu Theo Ngành Hàng',
      subtext: 'Tỷ trọng đóng góp doanh thu & hiệu quả sinh lời',
      left: 'center',
      top: 14,
      textStyle: { color: '#0f172a', fontSize: 16, fontWeight: 700 },
      subtextStyle: { color: '#64748b', fontSize: 12 }
    },
    {
      text: `${totalNetRev} Tỷ`,
      subtext: 'Tổng Doanh Thu',
      left: '49.5%',
      top: '51%',
      textAlign: 'center',
      textVerticalAlign: 'middle',
      textStyle: { color: '#0f172a', fontSize: 20, fontWeight: 700 },
      subtextStyle: { color: '#64748b', fontSize: 11, fontWeight: 500 }
    }
  ],
  tooltip: {
    trigger: 'item',
    backgroundColor: '#ffffff',
    borderColor: '#e2e8f0',
    borderWidth: 1,
    padding: [12, 16],
    extraCssText: 'box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); border-radius: 8px;',
    textStyle: { color: '#1e293b' },
    formatter: function(params) {
      const item = params.data;
      return `<div style="font-weight:700;color:#0f172a;margin-bottom:6px;font-size:13px;">${item.name}</div>
              <div style="font-size:12px;color:#475569;line-height:1.7;">
                Doanh thu thuần: <b style="color:#2563eb;">${item.value} tỷ VNĐ</b> (${params.percent}%)<br/>
                Lợi nhuận gộp: <b style="color:#10b981;">${item.profitBillion} tỷ VNĐ</b><br/>
                Biên lợi nhuận: <b style="color:#f59e0b;">${item.marginPercent}%</b><br/>
                Số lượt đơn hàng: <b>${item.orders} đơn</b>
              </div>`;
    }
  },
  legend: {
    orient: 'horizontal',
    bottom: 12,
    left: 'center',
    textStyle: { color: '#475569', fontSize: 12 },
    itemWidth: 10,
    itemHeight: 10,
    icon: 'circle'
  },
  // Bảng màu tương phản đẹp trên nền sáng
  color: ['#2563eb', '#10b981', '#f59e0b', '#8b5cf6'],
  series: [
    {
      name: 'Doanh Thu Thuần',
      type: 'pie',
      radius: ['45%', '68%'],
      center: ['50%', '54%'],
      avoidLabelOverlap: true,
      itemStyle: {
        borderRadius: 6,
        borderColor: '#ffffff',
        borderWidth: 2
      },
      label: {
        show: true,
        formatter: '{b}\n{d}%',
        color: '#334155',
        fontSize: 11,
        fontWeight: 500
      },
      labelLine: {
        show: true,
        length: 12,
        length2: 10,
        lineStyle: { color: '#cbd5e1' }
      },
      emphasis: {
        scale: true,
        scaleSize: 8,
        itemStyle: {
          shadowBlur: 10,
          shadowOffsetX: 0,
          shadowColor: 'rgba(0, 0, 0, 0.15)'
        }
      },
      data: donutData
    }
  ]
};

// 1. Tổng hợp dữ liệu theo sản phẩm
const productMap = {};

data.forEach(r => {
  if (r['Order_Status'] === 'Cancelled') return;

  const prodName = r['Product_Name'] ? String(r['Product_Name']).trim() : 'Khác';
  if (!productMap[prodName]) {
    productMap[prodName] = { netRevenue: 0, grossRevenue: 0, discountAmount: 0, qty: 0 };
  }

  const qty = Number(r['Order_Quantity']) || 0;
  const price = Number(r['Unit_Price']) || 0;
  const discountRate = Number(r['Discount_Rate']) || 0;

  const gross = qty * price;
  let netRev = Number(r['Net_Revenue']);
  let discAmt = Number(r['Discount_Amount']);

  if (isNaN(netRev) || netRev === 0) {
    discAmt = gross * discountRate;
    netRev = gross - discAmt;
  }

  productMap[prodName].netRevenue += netRev;
  productMap[prodName].grossRevenue += gross;
  productMap[prodName].discountAmount += discAmt;
  productMap[prodName].qty += qty;
});

// Sắp xếp top 10 sản phẩm theo doanh thu và đảo thứ tự để hiển thị trục dọc từ trên xuống
const sortedProducts = Object.keys(productMap)
  .map(name => {
    const item = productMap[name];
    const avgDiscountRate = item.grossRevenue > 0
      ? (item.discountAmount / item.grossRevenue) * 100
      : 0;
    return {
      name: name,
      netRevenue: Math.round((item.netRevenue / 1e9) * 100) / 100,
      discountAmount: Math.round((item.discountAmount / 1e6) * 10) / 10,
      discountRate: Math.round(avgDiscountRate * 10) / 10,
      qty: item.qty
    };
  })
  .sort((a, b) => b.netRevenue - a.netRevenue)
  .slice(0, 10)
  .reverse();

const productNames = sortedProducts.map(p => p.name);
const revenues = sortedProducts.map(p => p.netRevenue);

// 2. Cấu hình Option ECharts - Theme Sáng
return {
  backgroundColor: '#ffffff',
  title: {
    text: 'Top 10 Sản Phẩm Có Doanh Thu Thuần Cao Nhất',
    subtext: 'Kèm tỷ lệ chiết khấu bình quân & số lượng bán ra',
    left: 'center',
    top: 16,
    textStyle: { color: '#0f172a', fontSize: 16, fontWeight: 700 },
    subtextStyle: { color: '#64748b', fontSize: 12 }
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'shadow',
      shadowStyle: { color: 'rgba(241, 245, 249, 0.6)' }
    },
    backgroundColor: '#ffffff',
    borderColor: '#e2e8f0',
    borderWidth: 1,
    padding: [10, 14],
    extraCssText: 'box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); border-radius: 8px;',
    textStyle: { color: '#1e293b' },
    formatter: function(params) {
      const idx = params[0].dataIndex;
      const item = sortedProducts[idx];
      return `<div style="font-weight:700;color:#0f172a;margin-bottom:6px;">${item.name}</div>
              <div style="font-size:12px;color:#475569;line-height:1.6;">
                Doanh thu thuần: <b style="color:#2563eb;">${item.netRevenue} tỷ VNĐ</b><br/>
                Số lượng đã bán: <b style="color:#0f172a;">${item.qty.toLocaleString()} sp</b><br/>
                Chiết khấu trung bình: <b style="color:#e11d48;">${item.discountRate}%</b> (${item.discountAmount} triệu VNĐ)
              </div>`;
    }
  },
  grid: {
    left: '3%',
    right: '12%',
    bottom: '5%',
    top: '16%',
    containLabel: true
  },
  xAxis: {
    type: 'value',
    name: 'Tỷ VNĐ',
    nameTextStyle: { color: '#64748b' },
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: { color: '#64748b' },
    splitLine: { lineStyle: { color: '#f1f5f9', type: 'dashed' } }
  },
  yAxis: {
    type: 'category',
    data: productNames,
    axisLine: { lineStyle: { color: '#cbd5e1' } },
    axisTick: { show: false },
    axisLabel: { color: '#334155', fontSize: 12, fontWeight: 500 }
  },
  series: [
    {
      name: 'Doanh Thu Thuần',
      type: 'bar',
      data: revenues,
      barMaxWidth: 22,
      label: {
        show: true,
        position: 'right',
        formatter: function(param) {
          const item = sortedProducts[param.dataIndex];
          return `${param.value} tỷ  (-${item.discountRate}%)`;
        },
        color: '#1e40af',
        fontWeight: 600,
        fontSize: 11
      },
      itemStyle: {
        borderRadius: [0, 6, 6, 0],
        color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
          { offset: 0, color: '#3b82f6' },
          { offset: 1, color: '#60a5fa' }
        ])
      }
    }
  ]
};

// 1. Tổng hợp dữ liệu theo Sản phẩm / Ngành hàng để dựng bảng
const aggMap = {};

data.forEach(r => {
  if (r['Order_Status'] === 'Cancelled') return;

  const prodName = r['Product_Name'] ? String(r['Product_Name']).trim() : 'Khác';
  if (!aggMap[prodName]) {
    aggMap[prodName] = {
      name: prodName,
      category: r['Category'] || '',
      qty: 0,
      grossRev: 0,
      netRev: 0,
      cogs: 0,
      discountAmt: 0,
      orderCount: 0
    };
  }

  const qty = Number(r['Order_Quantity']) || 0;
  const price = Number(r['Unit_Price']) || 0;
  const cost = Number(r['Unit_Cost']) || 0;
  const discountRate = Number(r['Discount_Rate']) || 0;

  const gross = qty * price;
  let netRev = Number(r['Net_Revenue']);
  let discAmt = Number(r['Discount_Amount']);

  if (isNaN(netRev) || netRev === 0) {
    discAmt = gross * discountRate;
    netRev = gross - discAmt;
  }

  const cogs = qty * cost;

  aggMap[prodName].qty += qty;
  aggMap[prodName].grossRev += gross;
  aggMap[prodName].netRev += netRev;
  aggMap[prodName].cogs += cogs;
  aggMap[prodName].discountAmt += discAmt;
  aggMap[prodName].orderCount += 1;
});

// Chuyển đổi và sắp xếp theo Doanh thu thuần giảm dần
const tableRows = Object.values(aggMap)
  .map(item => {
    const profit = item.netRev - item.cogs;
    const margin = item.netRev > 0 ? (profit / item.netRev) * 100 : 0;
    const avgDiscRate = item.grossRev > 0 ? (item.discountAmt / item.grossRev) * 100 : 0;
    return {
      name: item.name,
      category: item.category,
      qty: item.qty,
      orders: item.orderCount,
      netRevBillion: Math.round((item.netRev / 1e9) * 100) / 100,
      cogsBillion: Math.round((item.cogs / 1e9) * 100) / 100,
      profitBillion: Math.round((profit / 1e9) * 100) / 100,
      marginPercent: Math.round(margin * 10) / 10,
      discPercent: Math.round(avgDiscRate * 10) / 10
    };
  })
  .sort((a, b) => b.netRevBillion - a.netRevBillion);

// Chuẩn bị dữ liệu hiển thị dạng bảng ma trận ngang (Hiển thị Top 12 mặt hàng tiêu biểu)
const displayRows = tableRows.slice(0, 12).reverse();
const productNames = displayRows.map(r => r.name);

// 2. Cấu hình Option ECharts hiển thị Bảng Dữ Liệu Kết Hợp Mini-Bar
return {
  backgroundColor: '#ffffff',
  title: {
    text: 'Bảng Số Liệu Chi Tiết Chỉ Số Kinh Doanh Theo Sản Phẩm',
    subtext: 'Thống kê Doanh thu thuần, Giá vốn, Lợi nhuận gộp & Biên lãi (%)',
    left: 'center',
    top: 16,
    textStyle: { color: '#0f172a', fontSize: 16, fontWeight: 700 },
    subtextStyle: { color: '#64748b', fontSize: 12 }
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'shadow',
      shadowStyle: { color: 'rgba(241, 245, 249, 0.8)' }
    },
    backgroundColor: '#ffffff',
    borderColor: '#e2e8f0',
    borderWidth: 1,
    padding: [12, 16],
    extraCssText: 'box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); border-radius: 8px;',
    textStyle: { color: '#1e293b' },
    formatter: function(params) {
      const idx = params[0].dataIndex;
      const row = displayRows[idx];
      return `<div style="font-weight:700;color:#0f172a;margin-bottom:8px;font-size:13px;">${row.name}</div>
              <div style="font-size:12px;color:#64748b;margin-bottom:6px;">Ngành hàng: <b style="color:#334155;">${row.category}</b></div>
              <table style="width:100%;font-size:12px;color:#334155;border-collapse:collapse;">
                <tr><td style="padding:2px 10px 2px 0;">Doanh thu thuần:</td><td style="text-align:right;font-weight:700;color:#2563eb;">${row.netRevBillion} tỷ VNĐ</td></tr>
                <tr><td style="padding:2px 10px 2px 0;">Giá vốn (COGS):</td><td style="text-align:right;font-weight:600;color:#64748b;">${row.cogsBillion} tỷ VNĐ</td></tr>
                <tr><td style="padding:2px 10px 2px 0;">Lợi nhuận gộp:</td><td style="text-align:right;font-weight:700;color:#10b981;">${row.profitBillion} tỷ VNĐ</td></tr>
                <tr><td style="padding:2px 10px 2px 0;">Biên lợi nhuận gộp:</td><td style="text-align:right;font-weight:700;color:#d97706;">${row.marginPercent}%</td></tr>
                <tr><td style="padding:2px 10px 2px 0;">Tỷ lệ chiết khấu TB:</td><td style="text-align:right;font-weight:600;color:#ef4444;">${row.discPercent}%</td></tr>
                <tr><td style="padding:2px 10px 2px 0;">Số lượng đã bán:</td><td style="text-align:right;font-weight:600;">${row.qty.toLocaleString()} sp (${row.orders} đơn)</td></tr>
              </table>`;
    }
  },
  legend: {
    data: ['Doanh Thu Thuần', 'Lợi Nhuận Gộp'],
    top: 55,
    textStyle: { color: '#475569', fontSize: 12 }
  },
  grid: {
    left: '3%',
    right: '22%',
    bottom: '4%',
    top: '18%',
    containLabel: true
  },
  xAxis: {
    type: 'value',
    name: 'Tỷ VNĐ',
    nameTextStyle: { color: '#64748b' },
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: { color: '#64748b' },
    splitLine: { lineStyle: { color: '#f1f5f9', type: 'dashed' } }
  },
  yAxis: {
    type: 'category',
    data: productNames,
    axisLine: { lineStyle: { color: '#cbd5e1' } },
    axisTick: { show: false },
    axisLabel: {
      color: '#1e293b',
      fontSize: 12,
      fontWeight: 500
    }
  },
  series: [
    {
      name: 'Doanh Thu Thuần',
      type: 'bar',
      data: displayRows.map(r => r.netRevBillion),
      barMaxWidth: 16,
      itemStyle: {
        borderRadius: [0, 4, 4, 0],
        color: '#3b82f6'
      }
    },
    {
      name: 'Lợi Nhuận Gộp',
      type: 'bar',
      data: displayRows.map(r => r.profitBillion),
      barMaxWidth: 16,
      label: {
        show: true,
        position: 'right',
        distance: 12,
        formatter: function(param) {
          const row = displayRows[param.dataIndex];
          return `{val|${row.profitBillion} tỷ}  {margin|(${row.marginPercent}%)}  {qty|[${row.qty} sp]}`;
        },
        rich: {
          val: { color: '#047857', fontWeight: 700, fontSize: 11 },
          margin: { color: '#b45309', fontWeight: 600, fontSize: 11 },
          qty: { color: '#64748b', fontSize: 10 }
        }
      },
      itemStyle: {
        borderRadius: [0, 4, 4, 0],
        color: '#10b981'
      }
    }
  ]
