// 1. Tổ chức dữ liệu 2 tầng: Tầng 1 (Ngành Hàng) và Tầng 2 (Sản phẩm trong Ngành)
const hierarchy = {};

sourceData.forEach(r => {
  if (r['Order_Status'] === 'Cancelled') return;

  const cat = r['Category'] ? String(r['Category']).trim() : 'Khác';
  const prod = r['Product_Name'] ? String(r['Product_Name']).trim() : 'Khác';

  const qty = Number(r['Order_Quantity']) || 0;
  const price = Number(r['Unit_Price']) || 0;
  const cost = Number(r['Unit_Cost']) || 0;
  const discountRate = Number(r['Discount_Rate']) || 0;

  let netRev = Number(r['Net_Revenue']);
  if (isNaN(netRev) || netRev === 0) {
    const gross = qty * price;
    netRev = gross - (gross * discountRate);
  }
  const profit = netRev - (qty * cost);

  if (!hierarchy[cat]) {
    hierarchy[cat] = { netRev: 0, profit: 0, products: {} };
  }
  hierarchy[cat].netRev += netRev;
  hierarchy[cat].profit += profit;

  if (!hierarchy[cat].products[prod]) {
    hierarchy[cat].products[prod] = { netRev: 0, profit: 0, qty: 0 };
  }
  hierarchy[cat].products[prod].netRev += netRev;
  hierarchy[cat].products[prod].profit += profit;
  hierarchy[cat].products[prod].qty += qty;
});

