                Doanh thu thuần: <b style="color:#2563eb;">${c.netRevBillion} tỷ VNĐ</b><br/>
                Tổng số đơn hàng: <b>${c.orders} đơn</b>
              </div>`;
    }
  },
  grid: {
    left: '4%',
    right: '12%',
    top: 75,
    bottom: '6%',
    containLabel: true
  },
  xAxis: {
    type: 'value',
    name: 'Tỷ VNĐ',
    nameTextStyle: { color: '#64748b' },
    axisLine: { show: false },
    axisLabel: { color: '#64748b' },
    splitLine: { lineStyle: { color: '#f1f5f9', type: 'dashed' } }
  },
  yAxis: {
    type: 'category',
    data: channelNames,
    axisLine: { lineStyle: { color: '#cbd5e1' } },
    axisTick: { show: false },
    axisLabel: { color: '#1e293b', fontSize: 12, fontWeight: 600 }
  },
  series: [
    {
      name: 'Doanh Thu Thuần',
      type: 'bar',
      data: revenueData,
      barMaxWidth: 20,
      label: {
        show: true,
        position: 'right',
        formatter: '{c} tỷ',
        color: '#2563eb',
        fontWeight: 600,
        fontSize: 11
      },
      itemStyle: {
        borderRadius: [0, 4, 4, 0],
